from lib import *
S = SS('g43')
steps = [
    step("10 万个 goroutine 阻塞在 channel 上,看 /memory/classes/heap/stacks 的增量:每个 goroutine 不递归直接阻塞,栈内存增加 195.5 MiB → 每个约 2050 字节(2 KiB 起步);先递归 20 层再阻塞(栈已长到 4 KiB)增加 391.0 MiB → 每个约 4100 字节;先递归 200 层再阻塞(栈长到 32 KiB)增加 3126.1 MiB → 每个约 32779 字节。", t=tl(S(1)), done=lidx(S(1), '递归   0 层'), mark=lidx(S(1), '递归  20 层', '递归 200 层'), b=bars([['不递归(字节)', 2050, '2050'], ['递归 20 层', 4100, '4100'], ['递归 200 层', 32779, '32779']], 32779, done=[0], mark=[1, 2]), kv=KV([['不递归', '约 2050 字节(2 KiB 起步)'], ['递归 20 层', '约 4100 字节(长到 4 KiB)'], ['递归 200 层', '约 32779 字节(长到 32 KiB)']], ['递归 200 层'])),
    step("栈增长的过程:main.rec 的函数头是 locals=0xd8(216 字节栈帧)。递归 100 层栈被搬动 3 次、0.04 ms;5000 层 9 次、0.66 ms;20 万层 14 次、20.57 ms。每次搬动发生的深度依次是 9、28、64、137、284、576、1161、2332、4672……,相邻两次的间隔 9、19、36、73、147、292、585、1171、2340 层——大约每次翻倍,最后两次在深度 74889 与 149788(新栈地址与旧栈地址差 +33554432、+67108864 字节,即 32 MiB、64 MiB)。第一次在 9 层:9 × 216 字节 ≈ 2 KiB。", t=tl(S(2)), done=lidx(S(2), 'main.rec 的函数头', '递归 100 层'), mark=lidx(S(2), '递归 5000 层', '递归 200000 层', '深度 149788'), b=bars([['100 层:搬动次数', 3, '3'], ['5000 层', 9, '9'], ['20 万层', 14, '14']], 14, done=[0], mark=[1, 2]), kv=KV([['栈帧', 'main.rec locals=0xd8(216 字节)'], ['第一次搬动', '深度 9(≈ 2 KiB 栈用完)'], ['后续', '间隔大约每次翻倍,每次容量翻倍'], ['20 万层', '共搬动 14 次,20.57 ms']], ['后续'])),
    step("栈会收缩:递归 20 万层之前栈内存 0.3 MiB;递归之后(函数已经返回)32.3 MiB;之后每次 runtime.GC() 约减半:16.31、8.34、4.38、2.38、1.38、0.88、0.62、0.53 MiB。", t=tl(S(3)), done=lidx(S(3), '递归 20 万层之前'), mark=lidx(S(3), '第 1 次', '第 4 次', '第 8 次'), b=bars([['函数返回后', 32.3, '32.3'], ['GC 1 次后', 16.31, '16.31'], ['GC 3 次后', 4.38, '4.38'], ['GC 8 次后', 0.53, '0.53']], 32.3, done=[3], mark=[0, 1, 2]), kv=KV([['返回后', '32.3 MiB(栈不会立刻变小)'], ['每次 GC', '约减半'], ['8 次 GC 之后', '0.53 MiB']], ['每次 GC'])),
    step("栈增长的成本:第一次递归 10 万层 7.79、6.58、5.48 ms(三轮),紧接着第二次(栈已经够大)0.74、0.73、0.73 ms——一次增长约花 5–7 ms 的差。小栈的增长也有成本:创建 20 万个 goroutine,每个递归 10 层(不需要增长)后退出,每个 365 ns;递归 100 层(需要增长)每个 893 ns。", t=tl(S(4)), done=lidx(S(4), '第 1 轮', '创建 200000 个 goroutine,每个递归 10 层'), mark=lidx(S(4), '创建 200000 个 goroutine,每个递归 100 层'), b=bars([['第一次递归 10 万层 ms', 7.79, '7.79'], ['第二次 ms', 0.74, '0.74'], ['递归 10 层的 goroutine(ns)', 365, '365'], ['递归 100 层', 893, '893']], 893, done=[1, 2], mark=[0, 3]), kv=KV([['需要增长 vs 不需要', '7.79 ms vs 0.74 ms(10 万层)'], ['小 goroutine', '10 层 365 ns;100 层(需增长)893 ns']], ['需要增长 vs 不需要'])),
    step("栈的上限:无限递归,默认 max stack = 1000000000(1 GB):runtime: goroutine stack exceeds 1000000000-byte limit,fatal error: stack overflow,退出码 2;debug.SetMaxStack(1 << 20) 之后:exceeds 1048576-byte limit,同样是 fatal error。这是 fatal error,不是 panic,recover 接不住。", t=tl(S(5)), mark=lidx(S(5), '默认', 'SetMaxStack(1 MiB)'), kv=KV([['默认上限', '1000000000 字节(1 GB)'], ['debug.SetMaxStack(1 MiB)', '1048576 字节'], ['溢出时', 'fatal error: stack overflow,退出码 2']], ['溢出时'])),
    step("函数序言里的栈检查:f 的函数头 locals=0x98;汇编里先 SUB $32, RSP, R17 算出栈指针预留后的位置,CMP R16, R17(R16 取自 goroutine 结构体里的一个字段,我认为是栈保护线,没有核对)、BLS 不够就跳到末尾 CALL runtime.morestack_noctxt——就是它触发栈增长。//go:nosplit 函数不做这个检查,所以一串 nosplit 调用会撑爆链接器的限制:40 个依次调用、每个有 64 字节局部数组的 nosplit 函数:go build 失败,main.n1: nosplit stack over 792 byte limit,并列出调用链(每层 grows 144 bytes)。", t=tl(S(6)), done=lidx(S(6), 'CMP', 'BLS'), mark=lidx(S(6), 'morestack_noctxt', 'nosplit stack over'), kv=KV([['序言', 'SUB 算出新栈顶,CMP 与栈保护线比较,BLS 跳转'], ['不够时', 'CALL runtime.morestack_noctxt → 分配更大的栈并拷贝'], ['//go:nosplit', '跳过检查;调用链总栈深度受限,超限时链接失败:nosplit stack over 792 byte limit']], ['不够时'])),
]
A = mkartg('g43', 43, 'Go,goroutine,栈增长,栈收缩,morestack,真实验证,动画演示',
    '在 Go 1.27.1 里实测 goroutine 栈:初始约 2 KiB(10 万个阻塞的 goroutine 每个约 2050 字节),递归时栈大约每次翻倍并被整体拷贝(20 万层递归搬动 14 次、共 20.57 ms);函数返回后栈不立即变小,每次 GC 约减半(32.3 MiB → 0.53 MiB);第一次深递归 5.5–7.8 ms,栈已够大时 0.73 ms;无限递归在 1 GB 上限处 fatal error;函数序言的栈检查与 //go:nosplit 链的链接限制。',
    'goroutine 能那么便宜,是因为它的栈从很小开始、不够再长。这篇用递归把栈撑大,从指针地址的变化直接看到栈被拷贝,量出每个 goroutine 的初始开销、增长与收缩的节奏、增长的成本、栈的上限,以及序言里那条触发增长的检查。',
    [('约 2 KiB', '一个刚创建的 goroutine 的栈内存(实测每个 2050 字节)'), ('14 次', '递归 20 万层时栈被整体搬动(翻倍)的次数,共 20.57 ms'), ('约减半', '深递归返回后,栈内存每次 GC 缩小的比例(32.3 → 16.3 → 8.3 → 4.4 MiB)')],
    [('初始栈', '<p>每个 goroutine 从大约 2 KiB 的栈开始(10 万个阻塞的 goroutine 每个增加约 2050 字节),所以可以轻松创建几十万个。栈用完时增长到更大的容量并保持,深一点的 goroutine 就占更多:递归 20 层后是 4 KiB,200 层后 32 KiB。</p>'),
     ('栈如何增长', '<p>实验里递归的每一层都带着一个指向底部变量的 <code>unsafe.Pointer</code>,运行时在拷贝栈时会改写栈上所有指针,所以只要它的值变了就说明栈被整体搬走了。第一次在栈用到约 2 KiB 时(9 层 × 216 字节栈帧),之后每隔的层数大约翻倍——栈的容量每次翻倍,新栈地址与旧栈不同。这也是为什么<b>指向栈上变量的指针不能被存成整数</b>(见前面 unsafe 一篇)。</p>'),
     ('栈会收缩', '<p>深递归返回后栈不会马上变小(32.3 MiB 还在),要等 GC:GC 发现栈只用了一小部分时把它缩小一半,所以每次 GC 约减半,八次之后回到 0.53 MiB。需要及时归还内存的程序,不要依赖栈收缩——它是渐进的。</p>'),
     ('成本', '<p>增长要分配新栈并拷贝旧栈:10 万层的第一次递归比第二次慢 7–10 倍(5.5–7.8 ms 对 0.73 ms)。对短命的小 goroutine,需要增长的一次约多花 500 ns(365 对 893 ns)。热路径里反复创建需要深栈的 goroutine,会反复付这个成本;用 goroutine 池复用栈是一种做法(本文没有试)。</p>'),
     ('上限', '<p>栈的上限默认是 1 GB(<code>debug.SetMaxStack</code> 可调),无限递归会在到达上限时 <code>fatal error: stack overflow</code>,不是 panic,<code>recover</code> 接不住,进程以退出码 2 结束。</p>'),
     ('序言与 nosplit', '<p>增长的触发点是每个函数序言里的比较:栈指针预留出这个函数的栈帧后,与 goroutine 的栈保护线比较,不够就调用 <code>runtime.morestack_noctxt</code>。<code>//go:nosplit</code> 函数不做这个比较,所以它们的调用链必须总共不超过链接器给的一小块预留空间(这里是 792 字节),否则链接时就报错。除了运行时内部,一般代码用不上 <code>nosplit</code>。</p>')],
    steps,
    [ENV_G + '。栈内存来自 runtime/metrics 的 /memory/classes/heap/stacks:bytes;搬动次数由递归时每层携带的 unsafe.Pointer 的值变化推断(第一次比较发生在第 1 层之后);函数头与序言来自 go build -gcflags=-S;栈上限的实验是独立进程(默认 1 GB 的那次要占用较多内存);每个数字来自一次运行',
     '没有验证:自适应初始栈大小(adaptivestackstart)的行为、栈增长算法里“翻倍”的具体规则(只从搬动间隔看出大致翻倍)、栈收缩的触发条件(只看到每次 GC 约减半)、amd64 上的栈帧与序言、不同帧大小下 792 字节限制的来源'],
    'goroutine 栈增长')
